import * as assert from 'assert';
import { GitIntegrationService } from '../../../src/git';
import { ContextKeyController } from '../../../src/selection';

// Live feasibility check (#3): opens a real Git repository with one linked worktree (generated by
// test/setup/createGitFixture.js as this suite's workspace folder — see .vscode-test.mjs) and
// confirms the built-in Git extension actually surfaces the linked worktree as its own Repository
// (kind: 'worktree'), validating the #2 discovery pipeline end to end against a live git process
// rather than only against the mocked shapes in worktreeNormalization.test.ts.
//
// Finding: SCM "selected" state is owned by VS Code core's Source Control view focus mechanism
// (ISCMViewService), which has no public API a test can script directly. The second test below
// therefore asserts internal consistency against whatever the live selection state is, rather than
// a specific true/false value; confirming the actual show/hide UX end to end is a manual Extension
// Development Host check until #4/#13 add broader coverage.
suite('Live Git worktree discovery (#3 feasibility spike)', function () {
  this.timeout(30000);

  let gitIntegration: GitIntegrationService;
  let contextKeys: ContextKeyController;

  suiteSetup(async () => {
    gitIntegration = new GitIntegrationService();
    await gitIntegration.activate();
    // Wait for both the linked worktree to appear *and* its HEAD state to settle: opening a
    // repository via the Git API returns before its status refresh (which populates HEAD) completes.
    await waitUntil(() => {
      const worktrees = gitIntegration.listWorktrees();
      return worktrees.length >= 2 && worktrees.every((w) => w.ref !== undefined);
    }, 20000);
    contextKeys = new ContextKeyController(gitIntegration);
  });

  suiteTeardown(() => {
    contextKeys.dispose();
    gitIntegration.dispose();
  });

  test('FR-001/FR-002/FR-003: discovers the main repository and its linked worktree live', () => {
    const worktrees = gitIntegration.listWorktrees();
    const main = worktrees.find((w) => w.isMain);
    const linked = worktrees.find((w) => !w.isMain);

    assert.ok(main, 'main repository should be discovered');
    assert.ok(linked, 'linked worktree should be discovered');
    assert.strictEqual(linked!.repositoryRoot.fsPath, main!.rootUri.fsPath);
    assert.strictEqual(linked!.ref, 'feature/x');
    assert.strictEqual(linked!.isDetached, false);
  });

  test('context keys stay consistent with live selection state', () => {
    const worktrees = gitIntegration.listWorktrees().filter((w) => !w.isMain);
    const anySelected = worktrees.some((w) => gitIntegration.isRepositorySelected(w.rootUri));
    assert.strictEqual(contextKeys.values.hasWorktrees, worktrees.length > 0);
    assert.strictEqual(contextKeys.values.visible, anySelected);
  });
});

async function waitUntil(predicate: () => boolean, timeoutMs: number): Promise<void> {
  const start = Date.now();
  while (!predicate()) {
    if (Date.now() - start > timeoutMs) {
      throw new Error('Timed out waiting for the Git extension to discover the fixture repository.');
    }
    await new Promise((resolve) => setTimeout(resolve, 200));
  }
}
